(() => {
  const FOOD_KEY = 'supervivencia-food-v1';
  const OSM_TILE = 'https://tile.openstreetmap.org/{z}/{x}/{y}.png';
  const RADIO = [
    ['VHF','145.500 MHz','Freqüència simplex de crida / coordinació','FM','📻'],
    ['VHF','145.550 MHz','Ús FM indicat a Espanya en la taula IARU R1','FM','🇪🇸'],
    ['UHF','433.500 MHz','Freqüència simplex de crida / coordinació','FM','📻'],
    ['UHF','433.550 MHz','Ús FM indicat a Espanya en la taula IARU R1','FM','🇪🇸'],
    ['HF','7.110 MHz','Centre d’activitat d’emergències IARU Regió 1','Veu · SSB','🇪🇺'],
    ['HF','3.760 MHz','Centre d’activitat d’emergències IARU Regió 1','Veu · SSB','🇪🇺'],
    ['HF','14.300 MHz','Centre d’activitat d’emergències IARU Regió 1','Veu · SSB','🇪🇺']
  ];
  const FOOD = [
    ['llegums','🫘','Llegums cuits'], ['tonyina','🐟','Tonyina i peix en llauna'],
    ['carn','🥫','Conserves de carn'], ['verdures','🍅','Tomàquet i verdures en conserva'],
    ['galetes','🥨','Galetes i crackers'], ['fruits-secs','🥜','Fruits secs'],
    ['barretes','🍫','Barretes energètiques'], ['fruita','🍑','Fruita en conserva'],
    ['llet','🥛','Llet UHT'], ['sucs','🧃','Sucs de llarga durada'],
    ['arros-pasta','🍚','Arròs i pasta'], ['cereals','🌾','Cereals']
  ];
  function loadFood() { try { return JSON.parse(localStorage.getItem(FOOD_KEY) || '{}'); } catch (_) { return {}; } }
  function saveFood(data) { localStorage.setItem(FOOD_KEY, JSON.stringify(data)); }
  function foodMenu(type) {
    const saved = loadFood();
    return `<div class="food-submenu" data-food-menu="${type}"><div class="food-title">🥫 Exemples de menjar per tenir preparat</div><div class="food-grid">${FOOD.map(([id, icon, name]) => { const key = `${type}-${id}`; return `<label class="food-option ${saved[key] ? 'done' : ''}"><input type="checkbox" data-food-item="${id}" data-food-type="${type}" ${saved[key] ? 'checked' : ''}><span>${icon}</span><span>${name}</span></label>`; }).join('')}</div><p>Selecciona també els aliments que ja tens preparats. Les seleccions es guarden al dispositiu.</p></div>`;
  }
  function syncFoodVisibility(input) { const menu = input.closest('.check')?.nextElementSibling; if (!menu?.classList.contains('food-submenu')) return; menu.hidden = input.checked; }
  function addFoodMenus() { document.querySelectorAll('input[data-id="food"]').forEach(input => { const label = input.closest('.check'); if (!label) return; const type = input.dataset.type || 'kit'; if (!label.nextElementSibling?.classList.contains('food-submenu')) label.insertAdjacentHTML('afterend', foodMenu(type)); syncFoodVisibility(input); }); }
  function toolCards() {
    return `<article class="card tile feature-tile" data-feature="map"><span class="emoji">🗺️</span><div><h3>Mapa real</h3><p>Mapa de carrers i carreteres amb OpenStreetMap.</p></div></article><article class="card tile feature-tile" data-feature="navigation"><span class="emoji">🧭</span><div><h3>Orientació i retorn</h3><p>Brúixola, punts guardats i registre del recorregut GPS.</p></div></article><article class="card tile feature-tile" data-feature="radio"><span class="emoji">📡</span><div><h3>Freqüències d’emergència</h3><p>HF · VHF · UHF per comunicacions d’emergència.</p></div></article>`;
  }
  function addTools() { document.querySelectorAll('.feature-tools').forEach(x => x.remove()); const pages = document.querySelectorAll('.page'); if (!pages.length) return; const page = pages[0]; const box = document.createElement('div'); box.className = 'feature-tools'; box.innerHTML = `<div class="section-title"><h2>🧭 Eines d’emergència</h2></div><div class="grid">${toolCards()}</div>`; page.appendChild(box); }
  const mapState = { lat: 41.75, lon: 1.75, zoom: 8, poi: true };
  function deg2num(lat, lon, z) { const n = 2 ** z; const x = (lon + 180) / 360 * n; const latRad = lat * Math.PI / 180; const y = (1 - Math.asinh(Math.tan(latRad)) / Math.PI) / 2 * n; return {x,y}; }
  function num2deg(x,y,z) { const n=2**z; const lon=x/n*360-180; const latRad=Math.atan(Math.sinh(Math.PI*(1-2*y/n))); return {lat:latRad*180/Math.PI,lon}; }
  function tileHtml(x,y,z,cls='') { const n=2**z; const xx=((x%n)+n)%n; if(y<0||y>=n)return ''; return `<img class="osm-tile ${cls}" draggable="false" src="${OSM_TILE.replace('{z}',z).replace('{x}',xx).replace('{y}',y)}" alt="">`; }
  const POI_KEY='supervivencia-pois-v1';
  function readSavedPOIs(){try{return JSON.parse(localStorage.getItem(POI_KEY)||'[]')}catch(_){return[]}}
  function writeSavedPOIs(rows){try{localStorage.setItem(POI_KEY,JSON.stringify(rows.slice(0,500)))}catch(_){alert('No hi ha prou espai al dispositiu per desar més punts.');}}
  function poiType(tags={}){if(tags.amenity==='hospital'||tags.healthcare==='hospital')return ['🏥','Hospital'];if(tags.amenity==='clinic'||tags.amenity==='doctors'||tags.healthcare==='clinic'||tags.healthcare==='centre'||tags.healthcare==='doctor')return ['🩺','CAP / centre de salut'];if(tags.amenity==='fire_station')return ['🚒','Bombers'];if(tags.amenity==='police')return ['👮','Policia'];if(tags.amenity==='shelter'||tags.emergency==='assembly_point')return ['🛟','Refugi / punt de trobada'];if(tags.amenity==='drinking_water')return ['💧','Aigua potable'];if(tags.amenity==='fuel')return ['⛽','Benzinera'];if(tags['communication:amateur_radio']==='yes')return ['📡','Punt de ràdio amateur'];return ['📍','Servei útil'];}
  function mapPage() {
    return `<div class="page feature-page"><button class="back-link" data-feature-back>‹ Tornar</button><section class="hero"><div class="hero-kicker">🗺️ MAPA REAL + PUNTS DESATS</div><h1>Mapa d’emergència</h1><p>Mapa de carrers i carreteres, GPS i serveis útils. Desa els punts de la zona abans de sortir per poder consultar-ne la llista sense cobertura.</p></section><div class="map-card real-map-card"><div class="map-toolbar"><button class="map-action" data-map-action="locate">📍 La meva ubicació</button><button class="map-action active" data-map-action="poi">🚨 Veure punts</button><button class="map-action" data-map-action="save-poi">⬇ Desar serveis de la zona</button><button class="map-reset" data-map-action="reset">⟳ Centrar</button></div><div class="map-controls"><button data-map-action="in" aria-label="Ampliar">＋</button><button data-map-action="out" aria-label="Reduir">−</button></div><div class="map-viewport real-map" id="mapViewport"><div class="map-canvas" id="mapCanvas"></div><div class="map-loading" id="mapLoading">Carregant mapa…</div><div class="map-location" id="mapLocation" hidden>📍</div><div class="map-pois" id="mapPois"></div></div></div><div class="map-attribution">© OpenStreetMap contributors · Dades de serveis: OpenStreetMap</div><div class="map-legend"><strong>📥 Punts guardats al dispositiu</strong><span>Desa hospitals, CAP/centres de salut, bombers, policia, refugis, punts de trobada, aigua potable i benzineres. Després podràs consultar la llista encara que no tinguis internet.</span><button class="map-action" data-map-action="saved-poi">📋 Consultar punts desats</button></div><div id="mapSavedList" class="map-saved-list" hidden></div><div class="info"><strong>ℹ️ Què funciona sense connexió?</strong><p>La llista de punts que hagis desat, els teus punts personals i el registre GPS. La cartografia de carrers continua necessitant internet; aquesta funció no descarrega mapes de fons.</p></div><div class="info"><strong>⚠️ Important</strong><p>Les dades d’OpenStreetMap poden ser incompletes o estar desactualitzades. Confirma sempre els serveis i segueix les indicacions oficials. No substitueix el 112.</p></div></div>`;
  }
  function renderTiles() {
    const vp=document.getElementById('mapViewport'),canvas=document.getElementById('mapCanvas'),loading=document.getElementById('mapLoading');if(!vp||!canvas)return;
    const z=mapState.zoom,center=deg2num(mapState.lat,mapState.lon,z),size=256,cols=Math.ceil(vp.clientWidth/size)+2,rows=Math.ceil(vp.clientHeight/size)+2;
    const startX=Math.floor(center.x-cols/2),startY=Math.floor(center.y-rows/2),offsetX=vp.clientWidth/2-(center.x-startX)*size,offsetY=vp.clientHeight/2-(center.y-startY)*size;
    canvas.innerHTML='';canvas.style.width=`${cols*size}px`;canvas.style.height=`${rows*size}px`;canvas.style.transform=`translate(${offsetX}px,${offsetY}px)`;
    for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const node=document.createElement('div');node.className='osm-tile-wrap';node.style.left=`${x*size}px`;node.style.top=`${y*size}px`;node.innerHTML=tileHtml(startX+x,startY+y,z);canvas.appendChild(node);}
    if(loading){loading.hidden=false;let count=0;const imgs=canvas.querySelectorAll('img');if(!imgs.length)loading.hidden=true;imgs.forEach(im=>{im.onload=()=>{count++;if(count>=Math.min(3,imgs.length))loading.hidden=true};im.onerror=()=>{count++;if(count>=Math.min(3,imgs.length))loading.hidden=true};});}
    if(mapState.poi)renderPOIMarkers();
  }
  function mapMove(dx,dy){const z=mapState.zoom,c=deg2num(mapState.lat,mapState.lon,z),next=num2deg(c.x-dx/256,c.y-dy/256,z);mapState.lat=Math.max(-85,Math.min(85,next.lat));mapState.lon=next.lon;renderTiles();}
  function locate(){if(!navigator.geolocation){alert('Aquest dispositiu no permet obtenir la ubicació.');return;}const loading=document.getElementById('mapLoading');if(loading){loading.textContent='Obtenint ubicació…';loading.hidden=false;}navigator.geolocation.getCurrentPosition(p=>{mapState.lat=p.coords.latitude;mapState.lon=p.coords.longitude;mapState.zoom=Math.max(mapState.zoom,14);const marker=document.getElementById('mapLocation');if(marker){marker.hidden=false;marker.style.left='50%';marker.style.top='50%';}renderTiles();},()=>alert('No s’ha pogut obtenir la ubicació. Revisa el permís de localització.'),{enableHighAccuracy:true,timeout:10000,maximumAge:60000});}
  function renderSavedPOIList(){const box=document.getElementById('mapSavedList');if(!box)return;const rows=readSavedPOIs();box.innerHTML=rows.length?'<div class="saved-poi-head"><strong>Serveis desats</strong><span>'+rows.length+'</span></div>'+rows.slice(0,100).map(p=>{const kind=poiType(p.tags||{});return '<article class="saved-poi-row"><span>'+kind[0]+'</span><div><strong>'+escapePOI(p.name||kind[1])+'</strong><small>'+kind[1]+(p.address?' · '+escapePOI(p.address):'')+'</small></div><button type="button" data-poi-center="'+p.lat+','+p.lon+'" aria-label="Situar al mapa">↗</button></article>';}).join('')+(rows.length>100?'<p class="small">Es mostren els primers 100 punts.</p>':''):'<p class="small">Encara no has desat cap servei. Connecta’t i prem «Desar serveis de la zona».</p>';box.hidden=false;box.querySelectorAll('[data-poi-center]').forEach(btn=>btn.addEventListener('click',()=>{const [lat,lon]=btn.dataset.poiCenter.split(',').map(Number);if(Number.isFinite(lat)&&Number.isFinite(lon)){mapState.lat=lat;mapState.lon=lon;mapState.zoom=15;renderTiles();box.hidden=true;}}));}
  function escapePOI(v){return String(v||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
  function renderPOIMarkers(){const box=document.getElementById('mapPois'),vp=document.getElementById('mapViewport');if(!box||!vp)return;box.innerHTML='';if(!mapState.poi)return;const z=mapState.zoom,c=deg2num(mapState.lat,mapState.lon,z),w=vp.clientWidth,h=vp.clientHeight,rows=readSavedPOIs();let visible=0;rows.forEach(p=>{const pos=deg2num(p.lat,p.lon,z),left=50+(pos.x-c.x)*256/w*100,top=50+(pos.y-c.y)*256/h*100;if(left< -5||left>105||top< -5||top>105)return;const kind=poiType(p.tags||{}),m=document.createElement('button');m.className='poi-marker';m.style.left=left+'%';m.style.top=top+'%';m.title=(p.name||kind[1])+' · '+kind[1];m.textContent=kind[0];m.addEventListener('click',()=>alert((p.name||kind[1])+'\n'+kind[1]+(p.address?'\n'+p.address:'')));box.appendChild(m);visible++;});if(!visible&&rows.length)box.innerHTML='<div class="poi-status">No hi ha punts desats en aquesta vista</div>';else if(!rows.length)box.innerHTML='<div class="poi-status">Desa serveis amb connexió per veure’ls aquí sense cobertura</div>';}
  async function downloadPOIs(){const btn=document.querySelector('[data-map-action="save-poi"]');if(btn){btn.disabled=true;btn.textContent='Descarregant…';}const lat=mapState.lat,lon=mapState.lon,span=Math.min(0.18,Math.max(0.035,120/2**mapState.zoom)),south=Math.max(-85,lat-span),north=Math.min(85,lat+span),west=lon-span,east=lon+span;const q=`[out:json][timeout:25];(nwr[amenity~"^(hospital|clinic|doctors|fire_station|police|shelter|drinking_water|fuel)$"](${south},${west},${north},${east});nwr[healthcare~"^(hospital|clinic|centre|doctor)$"](${south},${west},${north},${east});nwr[emergency=assembly_point](${south},${west},${north},${east});nwr["communication:amateur_radio"="yes"](${south},${west},${north},${east}););out center tags;`;try{const r=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'data='+encodeURIComponent(q)});if(!r.ok)throw new Error('HTTP '+r.status);const data=await r.json(),merged=new Map(readSavedPOIs().map(p=>[p.id,p]));(data.elements||[]).forEach(p=>{const plat=p.lat??p.center?.lat,plon=p.lon??p.center?.lon;if(!Number.isFinite(plat)||!Number.isFinite(plon))return;const tags=p.tags||{},kind=poiType(tags),id=String(p.type||'node')+'/'+p.id;merged.set(id,{id,lat:plat,lon:plon,name:tags.name||tags['name:ca']||tags['name:es']||kind[1],address:[tags['addr:street'],tags['addr:housenumber'],tags['addr:city']].filter(Boolean).join(' '),tags,savedAt:Date.now()});});const rows=[...merged.values()].sort((x,y)=>Math.abs(x.lat-lat)+Math.abs(x.lon-lon)-(Math.abs(y.lat-lat)+Math.abs(y.lon-lon)));writeSavedPOIs(rows);mapState.poi=true;renderPOIMarkers();renderSavedPOIList();if(btn){btn.textContent='✓ Serveis desats';btn.classList.add('active');}alert('S’han desat '+(data.elements||[]).length+' elements nous o actualitzats. Ara pots consultar la llista sense connexió.');}catch(e){if(btn)btn.textContent='⬇ Desar serveis de la zona';alert('No s’han pogut descarregar els serveis. Comprova la connexió i torna-ho a provar. Els punts que ja tenies desats es conserven.');}finally{if(btn)btn.disabled=false;}}
  function bindMap(){ const vp=document.getElementById('mapViewport'); if(!vp)return; renderTiles(); let sx=0,sy=0,drag=false,lastX=0,lastY=0; let tx=0,ty=0;const cv=document.getElementById('mapCanvas'),pv=document.getElementById('mapPois'),end=()=>{if(!drag)return;drag=false;cv.style.translate='';pv.style.translate='';const a=tx,b=ty;tx=ty=0;if(a||b)mapMove(a,b)}; vp.addEventListener('pointerdown',e=>{drag=true;tx=ty=0;lastX=e.clientX;lastY=e.clientY;vp.setPointerCapture(e.pointerId)}); vp.addEventListener('pointermove',e=>{if(!drag)return;tx+=e.clientX-lastX;ty+=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;const t=`${tx}px ${ty}px`;cv.style.translate=t;pv.style.translate=t}); vp.addEventListener('pointerup',end);vp.addEventListener('pointercancel',end); document.querySelectorAll('[data-map-action]').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.mapAction;if(a==='in')mapState.zoom=Math.min(18,mapState.zoom+1);if(a==='out')mapState.zoom=Math.max(3,mapState.zoom-1);if(a==='reset'){mapState.lat=41.75;mapState.lon=1.75;mapState.zoom=8;}if(a==='locate')return locate();if(a==='poi'){mapState.poi=!mapState.poi;b.classList.toggle('active',mapState.poi);renderPOIMarkers();return;}if(a==='save-poi'){downloadPOIs();return;}if(a==='saved-poi'){const box=document.getElementById('mapSavedList');if(box?.hidden)renderSavedPOIList();else if(box)box.hidden=true;return;}renderTiles();})); window.addEventListener('resize',renderTiles,{once:true}); }
  function radioPage(){ return `<div class="page feature-page"><button class="back-link" data-feature-back>‹ Tornar</button><section class="hero hero-radio"><div class="hero-kicker">📡 RADIOCOMUNICACIONS</div><h1>Freqüències d’emergència</h1><p>Freqüències de referència per radioaficionats. Escolta abans de transmetre i prioritza sempre el trànsit d’emergència.</p></section><div class="radio-note">⚠️ Les freqüències són centres d’activitat, no canals exclusius d’emergència. Pot haver-hi QRM i ús local.</div><div class="freq-list">${RADIO.map(r=>`<div class="freq-card"><div class="freq-top"><span>${r[4]} ${r[0]}</span><strong>${r[1]}</strong></div><p>${r[2]}</p><small>${r[3]}</small></div>`).join('')}</div><div class="info"><strong>📻 Regla ràpida</strong><p>En cas d’emergència, mantén l’escolta, deixa lliure la freqüència quan hi hagi trànsit prioritari i segueix les instruccions dels coordinadors.</p></div></div>`; }

  const PHONE_DATA = [
    {area:'Catalunya',group:'Emergències',icon:'🚨',name:'Emergències (112)',number:'112',note:'Policia, bombers, ambulàncies, rescats i qualsevol situació de risc. Gratuït, 24 h.',urgent:true},
    {area:'Catalunya',group:'Salut',icon:'🩺',name:'061 · Salut Respon',number:'061',note:'Consultes i problemes de salut que no siguin una emergència vital. 24 h.'},
    {area:'Catalunya',group:'Administració',icon:'🏛️',name:'Generalitat · informació',number:'012',note:'Informació i tràmits de la Generalitat.'},
    {area:'Catalunya',group:'Atenció i protecció',icon:'🛟',name:'Atenció a les dones · violència masclista',number:'900900120',note:'Atenció gratuïta i confidencial, 24 h.'},
    {area:'Catalunya',group:'Atenció i protecció',icon:'🧒',name:'Infància Respon',number:'116111',note:'Ajuda davant situacions de risc o maltractament a infants i adolescents.'},
    {area:'Catalunya',group:'Carreteres',icon:'🚗',name:'Servei Català de Trànsit · informació',number:'012',note:'Informació viària. Des de fora de Catalunya: 932 142 124.'},
    {area:'Espanya',group:'Emergències',icon:'🚨',name:'Emergències generals',number:'112',note:'Número únic d’emergències a tot l’Estat. Gratuït.',urgent:true},
    {area:'Espanya',group:'Seguretat',icon:'👮',name:'Policia Nacional',number:'091',note:'Policia Nacional.'},
    {area:'Espanya',group:'Seguretat',icon:'🛡️',name:'Guàrdia Civil',number:'062',note:'Guàrdia Civil.'},
    {area:'Espanya',group:'Atenció i protecció',icon:'🟣',name:'Atenció a víctimes de violència de gènere',number:'016',note:'Atenció gratuïta. No deixa rastre a la factura, però cal esborrar la trucada del registre del dispositiu.'},
    {area:'Espanya',group:'Atenció i protecció',icon:'💚',name:'Atenció a la conducta suïcida',number:'024',note:'Línia d’ajuda per a persones amb pensaments o risc de conducta suïcida.'},
    {area:'Europa',group:'Emergències',icon:'🇪🇺',name:'Número europeu d’emergències',number:'112',note:'Funciona als 27 països de la Unió Europea i en altres països europeus. Gratuït.',urgent:true},
    {area:'Estrangers',group:'Ajuda i assistència',icon:'🌍',name:'Emergències amb atenció multilingüe',number:'112',note:'A Catalunya poden atendre en català, castellà, anglès, francès i alemany; per a altres llengües poden activar interpretació.',urgent:true},
    {area:'Estrangers',group:'Viatges',icon:'🛂',name:'Consolat o ambaixada del teu país',number:'',note:'El telèfon d’emergència consular depèn de la nacionalitat i del país on et trobis. Desa’l abans de viatjar.',link:'https://www.exteriores.gob.es/'},
    {area:'Estrangers',group:'Viatges',icon:'🧳',name:'Assegurança de viatge',number:'',note:'Afegeix el telèfon d’assistència de la teva assegurança a Contactes personals.'}
  ];
  const PHONE_KEY = 'supervivencia-phone-contacts-v1';
  function readPhoneContacts(){try{return JSON.parse(localStorage.getItem(PHONE_KEY)||'[]')}catch(_){return[]}}
  function phonePage(){
    return `<div class="page feature-page"><button class="back-link" data-feature-back>‹ Tornar</button>
      <section class="hero hero-phone"><div class="hero-kicker">☎️ CONTACTES ESSENCIALS</div><h1>Guia telefònica</h1><p>Telèfons útils per a emergències, salut, seguretat i viatges. Disponible sense connexió.</p><a class="phone-call-main" href="tel:112">📞 TRUCAR AL 112</a></section>
      <div class="phone-warning">⚠️ El 112 és només per a emergències reals. Per a consultes sanitàries no vitals, utilitza el 061 a Catalunya.</div>
      <input class="phone-search" id="phoneSearch" type="search" placeholder="🔎 Cerca servei o número…" autocomplete="off">
      <div class="phone-tabs" id="phoneTabs">${['Catalunya','Espanya','Europa','Estrangers','Personals'].map((x,i)=>`<button class="phone-tab ${i===0?'active':''}" data-phone-area="${x}">${['🏴','🇪🇸','🇪🇺','🌍','👥'][i]} ${x}</button>`).join('')}</div>
      <div id="phoneList"></div>
      <section class="phone-personal"><h2>➕ Afegir contacte personal</h2><form id="phoneForm" class="form"><div class="field"><label>Nom o servei</label><input name="name" required placeholder="Ex. Assegurança de la llar"></div><div class="field"><label>Telèfon</label><input name="number" type="tel" required placeholder="Ex. +34 600 000 000"></div><div class="field"><label>Categoria</label><input name="group" placeholder="Ex. Família, assegurança, veïns"></div><button class="btn blue" type="submit">💾 Guardar contacte</button></form></section>
      <p class="small phone-source">Els números d’emergència s’han de verificar periòdicament. Fonts oficials: Generalitat de Catalunya, CAT112 i Administració General de l’Estat.</p>
    </div>`;
  }
  function renderPhoneList(){
    const list=document.getElementById('phoneList');if(!list)return;
    const area=document.querySelector('[data-phone-area].active')?.dataset.phoneArea||'Catalunya';
    const q=(document.getElementById('phoneSearch')?.value||'').toLocaleLowerCase('ca').trim();
    const custom=readPhoneContacts().map((c,i)=>({...c,area:'Personals',icon:'👤',id:i}));
    const entries=(area==='Personals'?custom:PHONE_DATA.filter(x=>x.area===area)).filter(x=>!q||[x.name,x.number,x.note,x.group].join(' ').toLocaleLowerCase('ca').includes(q));
    list.innerHTML=entries.length?entries.map(x=>`<article class="phone-card ${x.urgent?'phone-urgent':''}"><div class="phone-card-top"><span class="phone-icon">${x.icon}</span><div class="phone-copy"><strong>${escapePhone(x.name)}</strong><small>${escapePhone(x.group||'Contacte personal')}</small></div>${x.number? `<a class="phone-number" href="tel:${x.number.replace(/[^+0-9]/g,'')}">${escapePhone(x.number)}</a>`:''}</div><p>${escapePhone(x.note||'')}</p>${x.link?'<a class="phone-link" href="'+x.link+'" target="_blank" rel="noopener">Web oficial i directori consular ↗</a>':''}${area==='Personals'?'<button class="phone-delete" data-phone-delete="'+x.id+'">Eliminar contacte</button>':''}</article>`).join(''):'<div class="info">No hi ha contactes que coincideixin amb la cerca.</div>';
    list.querySelectorAll('[data-phone-delete]').forEach(b=>b.addEventListener('click',()=>{const c=readPhoneContacts();c.splice(Number(b.dataset.phoneDelete),1);localStorage.setItem(PHONE_KEY,JSON.stringify(c));renderPhoneList()}));
  }
  function escapePhone(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function bindPhone(){
    document.querySelectorAll('[data-phone-area]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-phone-area]').forEach(x=>x.classList.toggle('active',x===b));renderPhoneList()}));
    document.getElementById('phoneSearch')?.addEventListener('input',renderPhoneList);
    document.getElementById('phoneForm')?.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const c=readPhoneContacts();c.push({name:fd.get('name'),number:fd.get('number'),group:fd.get('group')||'Personal',note:'Contacte guardat en aquest dispositiu.'});localStorage.setItem(PHONE_KEY,JSON.stringify(c));e.currentTarget.reset();document.querySelectorAll('[data-phone-area]').forEach(x=>x.classList.toggle('active',x.dataset.phoneArea==='Personals'));renderPhoneList();alert('Contacte guardat al dispositiu.')});
    renderPhoneList();
  }

  // Guies orientades a decisions concretes; no repeteixen els consells generals.
  function guidesPage(){
    const guides = [
      {icon:'❤️',title:'Aturada cardíaca i RCP',tag:'Primers auxilis',body:`
        <ol><li>Comprova que l'entorn sigui segur i parla fort a la persona.</li><li>Si no respon i no respira amb normalitat (boquejades no són respiració normal), truca al <a href="tel:112">112</a> en mans lliures i demana un desfibril·lador (DEA).</li><li>Comença compressions al centre del pit: fort i ràpid, a 100–120 per minut, aproximadament 5–6 cm en un adult. Deixa que el pit torni a pujar.</li><li>Si saps fer ventilacions: 30 compressions i 2 ventilacions. Si no, fes compressions contínues.</li><li>Encén el DEA i segueix exactament les instruccions de veu. No toquis la persona durant l'anàlisi o la descàrrega.</li></ol><p class="guide-note">Continua fins que arribi ajuda, la persona respiri normalment o no puguis continuar. En infants i nadons la tècnica és diferent: segueix les instruccions del 112.</p>`},
      {icon:'🫁',title:'Ennuegament',tag:'Primers auxilis',body:`
        <ol><li><b>Si pot tossir i parlar:</b> anima-la a tossir. No li donis cops a l'esquena mentre la tos sigui efectiva.</li><li><b>Si no pot parlar, respirar ni tossir:</b> demana ajuda. Dona fins a 5 cops secs entre els omòplats, inclinant-la endavant.</li><li>Si no funciona, fes fins a 5 compressions abdominals cap endins i amunt. Alterna 5 cops i 5 compressions.</li><li>Truca al <a href="tel:112">112</a>. Si perd el coneixement, posa-la a terra i inicia RCP seguint les instruccions telefòniques.</li></ol><p class="guide-note">No facis compressions abdominals a nadons. En embaràs avançat o si no pots envoltar l'abdomen, calen compressions toràciques. Després d'una obstrucció greu, cal valoració sanitària.</p>`},
      {icon:'💧',title:'Aigua segura per beure',tag:'Autonomia',body:`
        <ul><li>Prioritza aigua embotellada precintada o la que indiquin les autoritats.</li><li>Si hi ha sospita de contaminació microbiològica i les autoritats no han prohibit bullir-la: porta-la a ebullició franca durant 1 minut i deixa-la refredar tapada.</li><li>El bullit no elimina combustibles, metalls, pesticides ni contaminació química. En aquests casos, no la consumeixis ni la facis servir per cuinar.</li><li>Guarda-la en recipients nets, aptes per a aliments i ben tancats. Separa l'aigua potable de productes químics i combustibles.</li></ul><p class="guide-note">En una alerta oficial d'aigua, segueix sempre les instruccions locals: bullir-la pot no ser suficient.</p>`},
      {icon:'☣️',title:'Monòxid de carboni (CO)',tag:'Risc invisible',body:`
        <ul><li>El CO no té olor ni color. Pot aparèixer amb estufes, brasers, generadors, barbacoes o motors en espais tancats o mal ventilats.</li><li>Mal de cap, mareig, nàusees, debilitat o confusió en diverses persones alhora són senyals d'alarma.</li><li>Surt immediatament a l'aire lliure, sense perdre temps buscant l'origen. Avisa tothom perquè surti.</li><li>Truca al <a href="tel:112">112</a> des de fora. No tornis a entrar ni intentis rescatar algú sense protecció.</li></ul><p class="guide-note">No facis servir mai generadors, barbacoes ni fogons de càmping dins de casa, garatge, tenda o vehicle.</p>`},
      {icon:'🏠',title:'Confinar-se o evacuar?',tag:'Prendre decisions',body:`
        <ul><li><b>Segueix primer l'ordre oficial.</b> Si Protecció Civil indica evacuació, prepara't i utilitza la ruta indicada.</li><li><b>Confinament:</b> és habitual davant un núvol tòxic o fum exterior. Entra en un edifici, tanca portes i finestres i atura la ventilació si així ho indiquen les autoritats.</li><li><b>Evacuació:</b> és necessària quan el lloc on ets deixa de ser segur, hi ha una ordre oficial o el risc immediat ho exigeix.</li><li>No travessis mai aigua inundada ni passis per fum dens per arribar a un lloc segur.</li><li>Si no pots sortir, truca al 112 i explica exactament on ets, quantes persones sou i què t'impedeix sortir.</li></ul><p class="guide-note">No hi ha una única resposta vàlida per a tots els incidents: el tipus de perill i les instruccions locals determinen què és més segur.</p>`},
      {icon:'🌲',title:'Perdre’s a la muntanya o al bosc',tag:'Supervivència a la natura',body:`<ol><li>Atura’t i evita continuar caminant sense orientació. Comprova si algú està ferit.</li><li>Si tens cobertura, truca al <a href="tel:112">112</a> i comparteix la ubicació GPS.</li><li>No segueixis dreceres desconegudes ni entris en barrancs o lleres.</li><li>Protegeix-te del fred, la calor, el vent i la pluja. Busca un lloc visible i segur.</li><li>Estalvia bateria i comparteix la ubicació amb el contacte d’emergència quan puguis.</li></ol><p class="guide-note">Abans de sortir, comunica la ruta i l’hora prevista de retorn. Porta mapa offline, aigua i roba adequada.</p>`},
      {icon:'🔥',title:'Foc segur a l’exterior',tag:'Supervivència a la natura',body:`<ul><li>Encén foc només quan estigui permès i no hi hagi prohibicions ni risc d’incendi. Consulta els avisos oficials.</li><li>Utilitza zones habilitades, lluny de vegetació i materials inflamables. No facis foc amb vent fort.</li><li>No utilitzis gasolina ni alcohol per encendre’l i no el deixis mai sense vigilància.</li><li>Apaga’l completament amb aigua, remena les brases i torna a mullar fins que tot sigui fred.</li></ul><p class="guide-note">No arrisquis un incendi forestal per aconseguir foc. Prioritza refugi i roba seca.</p>`},
      {icon:'🏕️',title:'Refugi i protecció tèrmica',tag:'Supervivència a la natura',body:`<ul><li>Tria un lloc fora de lleres, barrancs, zones inundables i vessants inestables.</li><li>Aïlla’t del terra amb una manta tèrmica, motxilla o material sec.</li><li>Mantén la roba seca i posa capes. Cobreix cap, mans i peus quan faci fred.</li><li>Amb calor, busca ombra, redueix l’esforç i hidrata’t sovint.</li></ul><p class="guide-note">No facis servir fogons, brasers ni generadors dins d’una tenda o refugi tancat: el monòxid de carboni pot ser mortal.</p>`},
      {icon:'🔌',title:'Autonomia a casa: llum, aigua i aliments',tag:'Autonomia',body:`<ul><li>Guarda aigua potable i aliments que no necessitin nevera ni una cocció llarga. Adapta les quantitats a les persones i mascotes de casa.</li><li>Carrega power banks, llanternes i ràdios; comprova les piles i guarda cables compatibles.</li><li>Durant una apagada, mantén nevera i congelador tancats. No facis servir generadors ni barbacoes a l’interior.</li><li>Identifica les claus de pas de l’aigua i del gas i aprèn a tallar el subministrament si és segur.</li><li>Revisa caducitats, medicació necessària, efectiu i documents cada sis mesos.</li></ul><p class="guide-note">Segueix les instruccions oficials sobre l’aigua de xarxa i la conservació dels aliments després d’una apagada o inundació.</p>`},
      {icon:'🚗',title:'Emergència mentre condueixes',tag:'Desplaçaments',body:`<ol><li>Atura’t en un lloc segur quan sigui possible. Encén els intermitents d’emergència.</li><li>Allunya’t del trànsit i situa’t darrere de la barrera de seguretat quan sigui segur.</li><li>No travessis fum dens ni aigua acumulada a la calçada.</li><li>Truca al <a href="tel:112">112</a> si hi ha ferits o perill. Indica carretera, sentit i punt quilomètric.</li><li>Porta al vehicle aigua, llanterna, armilla, carregador i farmaciola.</li></ol><p class="guide-note">La seguretat de les persones és prioritària. Segueix les instruccions dels serveis d’emergència.</p>`},
      {icon:'📵',title:'Sense cobertura ni Internet',tag:'Comunicacions',body:`<ul><li>Prova una trucada al <a href="tel:112">112</a>: el mòbil pot utilitzar una altra xarxa disponible, però no està garantit si no n’hi ha cap.</li><li>Activa l’estalvi de bateria i envia missatges curts quan recuperis cobertura.</li><li>Fes servir els mapes descarregats. El GPS pot funcionar sense dades mòbils.</li><li>Si el pla familiar ho preveu, ves al punt de trobada acordat només si el trajecte és segur.</li><li>Escolta la ràdio i evita desplaçaments innecessaris fins a tenir informació fiable.</li></ul><p class="guide-note">Una aplicació no substitueix el 112, les alertes oficials ni una ràdio independent.</p>`},
      {icon:'🩹',title:'Ferides i talls',tag:'Primers auxilis',body:`<ol><li>Renta’t les mans i protegeix-te amb guants si en tens.</li><li>Si sagna, fes pressió directa amb una gasa o roba neta fins que s’aturi.</li><li>Quan el sagnat sigui lleu, neteja la ferida amb aigua potable i cobreix-la amb un apòsit net.</li><li>No retiris objectes clavats ni exploris ferides profundes.</li><li>Demana valoració sanitària si és profunda, molt bruta, per mossegada, afecta ulls/cara/articulacions o no deixa de sagnar.</li></ol><p class="guide-note">Si l’hemorràgia és abundant o la persona es troba malament, truca al 112 i mantén la pressió.</p><a href="https://canalsalut.gencat.cat/ca/salut-a-z/p/primers-auxilis/hemorragies/index.html" target="_blank" rel="noopener">Canal Salut · Hemorràgies ↗</a>`},
      {icon:'🔥',title:'Cremades',tag:'Primers auxilis',body:`<ol><li>Assegura’t que no hi hagi perill i allunya la persona de la font de calor si és segur.</li><li>Refreda la zona amb aigua corrent fresca durant uns 20 minuts, sense gel.</li><li>Retira anells, rellotges o roba no adherida abans que s’infli la zona.</li><li>No rebentis butllofes ni hi posis oli, pasta de dents, mantega o cremes casolanes.</li><li>Cobreix-la suaument amb un apòsit estèril no adherent o un drap net.</li></ol><p class="guide-note">Truca al 112 si és extensa, profunda, química o elèctrica, afecta cara, mans, genitals o vies respiratòries, o la persona està greu. No arrenquis roba enganxada.</p><a href="https://canalsalut.gencat.cat/ca/salut-a-z/p/primers-auxilis/cremades/index.html" target="_blank" rel="noopener">Canal Salut · Cremades ↗</a>`},
      {icon:'🦴',title:'Possible fractura o lesió greu',tag:'Primers auxilis',body:`<ol><li>Evita moure la persona si sospites lesió de columna, pelvis o fractura greu, tret que hi hagi perill immediat.</li><li>Demana ajuda i truca al 112 si hi ha deformitat, ferida oberta, dolor intens, pèrdua de sensibilitat o traumatisme important.</li><li>Mantén la zona quieta en la posició trobada. No intentis redreçar l’os ni recol·locar una articulació.</li><li>Si hi ha ferida, cobreix-la amb material net sense pressionar un os exposat.</li><li>Vigila la respiració i protegeix la persona del fred fins que arribi ajuda.</li></ol><p class="guide-note">No donis menjar, beguda ni medicació. Si el cas és lleu, demana orientació sanitària per valorar-la.</p>`},
      {icon:'🌡️',title:'Cop de calor',tag:'Primers auxilis',body:`<ol><li>Porta la persona a l’ombra o a un espai fresc i truca al 112 si està confosa, molt calenta, convulsiona o perd el coneixement.</li><li>Refreda-la de seguida: treu roba sobrant, mulla la pell amb aigua fresca i venta-la.</li><li>Aplica fred embolicat a coll, aixelles i engonals si en tens.</li><li>No deixis sola la persona i vigila la respiració.</li><li>Només si està completament desperta i pot empassar amb normalitat, ofereix petits glops d’aigua.</li></ol><p class="guide-note">No donis líquids a una persona confusa, somnolenta o inconscient. No esperis que millori abans de demanar ajuda.</p><a href="https://canalsalut.gencat.cat/ca/salut-a-z/p/primers-auxilis/cop-calor/index.html" target="_blank" rel="noopener">Canal Salut · Cop de calor ↗</a>`},
      {icon:'❄️',title:'Hipotèrmia i fred intens',tag:'Primers auxilis',body:`<ol><li>Truca al 112 si hi ha confusió, somnolència marcada, parla lenta, pèrdua de coordinació o disminució de consciència.</li><li>Protegeix la persona del fred i del vent; trasllada-la a un lloc resguardat si és segur.</li><li>Retira la roba mullada amb cura i cobreix-la amb mantes, inclòs el cap.</li><li>Escalfa-la gradualment. Evita fregar braços o cames i no utilitzis calor directa intensa.</li><li>Si està completament desperta i empassa bé, pot prendre una beguda tèbia sense alcohol.</li></ol><p class="guide-note">No donis begudes a una persona inconscient o amb consciència alterada. Manipula-la amb suavitat i segueix el 112.</p><a href="https://treball.gencat.cat/ca/ambits/seguretat_i_salut_laboral/riscos_i_condicions_treball/mesures_per_risc/fred/ci/primers_auxilis/" target="_blank" rel="noopener">Generalitat · Hipotèrmia ↗</a>`},
      {icon:'🩸',title:'Hemorràgia greu',tag:'Primers auxilis',body:`
        <ol><li>Protegeix-te si és possible amb guants o una barrera. Truca al <a href="tel:112">112</a> o fes que algú ho faci.</li><li>Aplica pressió ferma i contínua directament sobre la ferida amb una gasa o roba neta.</li><li>Si s'empapa, posa més material a sobre sense retirar el primer i mantén la pressió.</li><li>Si hi ha un objecte clavat, no el retiris: pressiona al voltant.</li><li>No retiris el material inicial ni improvisis un torniquet. Segueix les instruccions del 112 sobre qualsevol dispositiu específic.</li></ol><p class="guide-note">No donis menjar ni beguda. Mantén la persona estirada i abrigada, vigilant la respiració.</p>`}
    ];
    return `<div class="page feature-page"><button class="back-link" data-feature-back>‹ Tornar</button><section class="hero"><div class="hero-kicker">📘 GUIES PRÀCTIQUES</div><h1>Què cal fer, pas a pas</h1><p>Guies curtes per a situacions diferents. Tria només el tema que necessites; no són una substitució de la formació ni de les instruccions del 112.</p></section><div class="guide-list">${guides.map((g,i)=>`<details class="guide-card"><summary><span class="guide-icon">${g.icon}</span><span class="guide-heading"><b>${g.title}</b><small>${g.tag}</small></span><span class="guide-chevron">＋</span></summary><div class="guide-body">${g.body}</div></details>`).join('')}</div><div class="info"><strong>📞 En cas de perill immediat</strong><p>Truca al 112. Posa el telèfon en mans lliures i segueix les instruccions de l'operador.</p><a class="call112" href="tel:112">Trucar al 112</a></div><p class="small guide-source">Material orientatiu basat en Canal Salut i SEM. No substitueix una formació presencial ni les instruccions del 112. <a href="https://canalsalut.gencat.cat/ca/salut-a-z/p/primers-auxilis/" target="_blank" rel="noopener">Consultar totes les guies oficials de Canal Salut ↗</a></p><div class="info"><strong>🎯 Practica què faries</strong><p>Posa a prova les teves decisions en situacions simulades, sense risc real.</p><button class="btn blue" type="button" data-feature="scenario">Obrir simulador d’emergències</button></div></div>`;
  }


  const SIM_CASES=[
    {title:'Fum al replà',scene:'Sents l’alarma i veus fum al replà. La porta de casa encara no és calenta.',q:'Quina és la primera decisió?',opts:[['Sortir immediatament pel replà','No és segur travessar fum o una via d’evacuació compromesa.'],['Comprovar la porta i seguir les instruccions del 112; si la sortida no és segura, confinar-se','Correcte: no t’exposis al fum. Comprova la porta sense obrir-la si és calenta i comunica on ets.'],['Agafar totes les pertinences abans de decidir','No perdis temps ni t’exposis per recuperar objectes.']],correct:1,why:'En un incendi, la ruta pot estar compromesa. No utilitzis l’ascensor, truca al 112 i segueix les indicacions dels bombers.'},
    {title:'Persona amb sagnat abundant',scene:'Una persona té una ferida profunda al braç i la sang surt de manera abundant.',q:'Què fas primer?',opts:[['Pressió directa ferma amb material net i trucada al 112','Correcte: pressió contínua i activar emergències són prioritaris.'],['Rentar la ferida abans de fer res','No: el sagnat greu s’ha de controlar de seguida.'],['Retirar qualsevol objecte clavat','No retiris objectes clavats; pressiona al voltant i segueix el 112.']],correct:0,why:'Mantén la pressió sense aixecar contínuament la gasa. Si s’empapa, afegeix material a sobre.'},
    {title:'Persona molt afectada per la calor',scene:'Després d’estar al sol, una persona està confosa, molt calenta i camina amb dificultat.',q:'Quina actuació és més adequada?',opts:[['Donar-li molta aigua de seguida','No donis líquids si està confosa: podria ennuegar-se.'],['Portar-la a un lloc fresc, començar a refredar-la i trucar al 112','Correcte: pot ser un cop de calor, una emergència mèdica.'],['Fer-la caminar perquè es recuperi','No: atura l’esforç i inicia el refredament.']],correct:1,why:'Refreda-la amb aigua fresca i ventilació. No esperis a veure si millora abans de demanar ajuda.'},
    {title:'Et perds caminant',scene:'La boira puja, no reconeixes el camí i la bateria del telèfon és baixa.',q:'Què convé fer?',opts:[['Continuar baixant pel primer corriol','No segueixis una ruta desconeguda ni entris en barrancs.'],['Aturar-te en un lloc segur, valorar la situació i trucar al 112 si necessites rescat','Correcte: evita empitjorar la situació, comparteix ubicació si pots i estalvia bateria.'],['Apagar el telèfon i caminar fins a trobar cobertura','No: mantén la possibilitat de demanar ajuda i utilitza el GPS si funciona.']],correct:1,why:'No improvisis dreceres. Protegeix-te del fred i la humitat, comunica la posició i segueix les instruccions del 112.'}
  ];
  let simIndex=0,simAnswer=null,simScore=0;
  function scenarioPage(){
    const s=SIM_CASES[simIndex],done=simAnswer!==null;
    return '<div class="page feature-page"><button class="back-link" data-feature-back>‹ Tornar</button><section class="hero"><div class="hero-kicker">🎯 ENTRENAMENT</div><h1>Simulador d’emergències</h1><p>Situacions breus per practicar decisions. No són consells personalitzats ni substitueixen els serveis d’emergència.</p></section><div class="sim-progress"><span>Situació '+(simIndex+1)+' de '+SIM_CASES.length+'</span><span>'+simScore+' decisions encertades</span></div><section class="info"><div class="sim-scene"><small>ESCENARI</small><h2>'+s.title+'</h2><p>'+s.scene+'</p></div><h3>'+s.q+'</h3><div class="sim-options">'+s.opts.map((o,i)=>'<button class="sim-option" data-sim-answer="'+i+'" '+(done?'disabled':'')+'>'+String.fromCharCode(65+i)+'. '+o[0]+'</button>').join('')+'</div>'+(done?'<div class="sim-feedback '+(simAnswer===s.correct?'good':'review')+'"><b>'+(simAnswer===s.correct?'✔ Bona decisió':'Cal revisar aquesta decisió')+'</b><p>'+s.why+'</p><small>'+s.opts[simAnswer][1]+'</small></div><button class="btn blue" id="simNext">'+(simIndex===SIM_CASES.length-1?'Veure resultat':'Següent situació')+'</button>':'<p class="small">Tria una resposta per veure’n l’explicació.</p>')+'</section><p class="small">Simulació educativa. En una emergència real, truca al 112 i segueix l’operador.</p></div>';
  }
  function scenarioAnswer(choice){if(simAnswer!==null)return;simAnswer=choice;if(choice===SIM_CASES[simIndex].correct)simScore++;const m=document.querySelector('#main');if(m)m.innerHTML=scenarioPage();document.getElementById('simNext')?.addEventListener('click',scenarioNext);document.querySelectorAll('[data-sim-answer]').forEach(b=>b.addEventListener('click',()=>scenarioAnswer(Number(b.dataset.simAnswer))));}
  function scenarioNext(){if(simIndex===SIM_CASES.length-1){const m=document.querySelector('#main');if(m)m.innerHTML='<div class="page feature-page"><section class="hero"><div class="hero-kicker">🏁 RESULTAT</div><h1>'+simScore+' / '+SIM_CASES.length+'</h1><p>Has completat el simulador. Repassa les explicacions de les respostes.</p></section><div class="info"><p>Practica de nou més endavant: conèixer els passos bàsics ajuda a mantenir la calma.</p><button class="btn blue" id="simRestart">Tornar a començar</button><button class="btn light" data-feature-back>Sortir</button></div></div>';document.getElementById('simRestart')?.addEventListener('click',scenarioRestart);return;}simIndex++;simAnswer=null;const m=document.querySelector('#main');if(m)m.innerHTML=scenarioPage();document.querySelectorAll('[data-sim-answer]').forEach(b=>b.addEventListener('click',()=>scenarioAnswer(Number(b.dataset.simAnswer))));}
  function scenarioRestart(){simIndex=0;simAnswer=null;simScore=0;const m=document.querySelector('#main');if(m)m.innerHTML=scenarioPage();document.querySelectorAll('[data-sim-answer]').forEach(b=>b.addEventListener('click',()=>scenarioAnswer(Number(b.dataset.simAnswer))));}
  const NAV_KEY='supervivencia-nav-v1', NAV_TRACK_KEY='supervivencia-track-v1'; let navWatch=null,navLast=null,navTrack=(()=>{try{return JSON.parse(localStorage.getItem(NAV_TRACK_KEY)||'[]')}catch(_){return []}})();
  const navEsc=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function navLoad(){try{return JSON.parse(localStorage.getItem(NAV_KEY)||'{"beacons":[]}')}catch(_){return {beacons:[]}}}
  function navSave(s){try{localStorage.setItem(NAV_KEY,JSON.stringify(s));return true}catch(_){return false}}
  function navDistance(a,b){const R=6371000,p1=a.lat*Math.PI/180,p2=b.lat*Math.PI/180,dp=(b.lat-a.lat)*Math.PI/180,dl=(b.lon-a.lon)*Math.PI/180,x=Math.sin(dp/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2;return 2*R*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
  function navBearing(a,b){const p1=a.lat*Math.PI/180,p2=b.lat*Math.PI/180,dl=(b.lon-a.lon)*Math.PI/180;return (Math.atan2(Math.sin(dl)*Math.cos(p2),Math.cos(p1)*Math.sin(p2)-Math.sin(p1)*Math.cos(p2)*Math.cos(dl))*180/Math.PI+360)%360}
  function navCompassName(d){return ['N','NE','E','SE','S','SW','W','NO'][Math.round(d/45)%8]}
  function navGPS(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(new Error('GPS no disponible'));navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lon:p.coords.longitude,accuracy:p.coords.accuracy,alt:p.coords.altitude,time:p.timestamp}),reject,{enableHighAccuracy:true,timeout:15000,maximumAge:5000})})}
  function navStatus(msg){const el=document.getElementById('navStatus');if(el)el.textContent=msg}
  function navPage(){const s=navLoad(),beacons=s.beacons||[];return '<div class="page feature-page nav-page"><button class="back-link" data-feature-back>‹ Tornar</button><section class="hero"><div class="hero-kicker">🧭 ORIENTACIÓ DE MUNTANYA</div><h1>Orientació i retorn</h1><p>Eines GPS del telèfon per guardar el punt de partida, registrar el trajecte i orientar-te cap a un punt guardat.</p></section><div class="nav-compass-card"><div class="nav-compass"><div class="nav-compass-ring"><span class="n">N</span><span class="e">E</span><span class="s">S</span><span class="w">O</span><div class="nav-needle">▲</div></div></div><strong id="navHeadingText">Brúixola no calibrada</strong><small>La brúixola depèn dels sensors del dispositiu i pot no estar disponible. Si el rumb balla, allunya’t d’imants i metall i mou el telèfon suaument fent un vuit per recalibrar-lo.</small><button class="map-action" id="navCompassBtn">Activar brúixola</button></div><div class="info"><h2>📍 La meva ubicació</h2><div class="nav-position" id="navPosition">Prem «Obtenir GPS» per llegir la posició.</div><button class="btn blue" id="navLocate">📍 Obtenir GPS</button><div id="navAccuracy" class="small"></div></div><div class="info"><h2>🏁 Punt de partida i punts guardats</h2><p>Guarda el lloc on deixes el vehicle, una cruïlla o un refugi.</p><div class="field"><label>Nom del punt</label><input id="navBeaconName" maxlength="50" placeholder="Ex. Cotxe, refugi, cruïlla..."></div><button class="btn blue" id="navSaveBeacon">＋ Guardar la ubicació actual</button><div class="nav-beacons" id="navBeacons">'+(beacons.length?beacons.map((b,i)=>'<div class="nav-beacon"><div><b>'+navEsc(b.name)+'</b><small>'+b.lat.toFixed(5)+', '+b.lon.toFixed(5)+'</small></div><button class="map-action" data-nav-go="'+i+'">Tornar-hi</button><button class="phone-delete-icon" data-nav-del="'+i+'" aria-label="Eliminar punt">🗑️</button></div>').join(''):'<p class="small">Encara no tens cap punt guardat.</p>')+'</div><div id="navTarget" class="nav-target" hidden></div></div><div class="info"><h2>🥾 Registrar el recorregut</h2><p>Inicia el registre abans de caminar. Mantén l’app oberta i la pantalla activa: el navegador pot aturar el GPS en segon pla.</p><div class="nav-track-stats"><div><small>Distància GPS</small><b id="navTrackDistance">0 m</b></div><div><small>Punts registrats</small><b id="navTrackCount">0</b></div><div><small>Temps</small><b id="navTrackTime">0 min</b></div></div><div class="nav-actions"><button class="btn blue" id="navTrackStart">▶ Iniciar registre</button><button class="btn" id="navTrackStop" disabled>■ Aturar</button><button class="btn" id="navTrackExport" disabled>⇩ Exportar GPX</button><button class="btn" id="navTrackClear" disabled>🗑️ Esborrar</button></div><p id="navStatus" class="small">El registre només comença quan ho demanes.</p></div><div class="info nav-warning"><strong>⚠️ Seguretat</strong><ul><li>El rumb del mòbil pot ser imprecís; contrasta’l amb mapa i terreny.</li><li>El GPS pot fallar en barrancs, boscos densos i túnels.</li><li>El registre en segon pla no està garantit en una PWA.</li><li>Si et perds, atura’t en un lloc segur i truca al 112 si necessites ajuda. No segueixis un rumb desconegut ni baixis per barrancs.</li></ul><a href="https://web.gencat.cat/ca/ciutadania/emergencies-seguretat/seguretat-muntanya" target="_blank" rel="noopener">Consells oficials de seguretat a la muntanya ↗</a></div></div>'}
  function navRenderBeacons(){const el=document.getElementById('navBeacons');if(!el)return;const s=navLoad();el.innerHTML=s.beacons.length?s.beacons.map((b,i)=>'<div class="nav-beacon"><div><b>'+navEsc(b.name)+'</b><small>'+b.lat.toFixed(5)+', '+b.lon.toFixed(5)+'</small></div><button class="map-action" data-nav-go="'+i+'">Tornar-hi</button><button class="phone-delete-icon" data-nav-del="'+i+'">🗑️</button></div>').join(''):'<p class="small">Encara no tens cap punt guardat.</p>';el.querySelectorAll('[data-nav-go]').forEach(b=>b.addEventListener('click',()=>navTarget(s.beacons[Number(b.dataset.navGo)])));el.querySelectorAll('[data-nav-del]').forEach(b=>b.addEventListener('click',()=>{s.beacons.splice(Number(b.dataset.navDel),1);navSave(s);navRenderBeacons()}))}
  function navTarget(target){const box=document.getElementById('navTarget');if(!box)return;box.hidden=false;navGPS().then(p=>{const d=navDistance(p,target),br=navBearing(p,target);box.innerHTML='<div class="nav-target-bearing">'+Math.round(br)+'° · '+navCompassName(br)+'</div><b>'+navEsc(target.name)+'</b><p>Distància en línia recta: <strong>'+(d<1000?Math.round(d)+' m':(d/1000).toFixed(2)+' km')+'</strong></p><small>Rumb aproximat, no és una ruta caminable ni evita obstacles.</small>'}).catch(()=>box.textContent='No s’ha pogut obtenir el GPS. Revisa els permisos.')}
  function navOrientation(e){let h=typeof e.webkitCompassHeading==='number'?e.webkitCompassHeading:(typeof e.alpha==='number'?(360-e.alpha)%360:null);if(h==null)return;const ring=document.querySelector('.nav-compass-ring');if(ring)ring.style.transform='rotate('+(-h)+'deg)';const label=document.getElementById('navHeadingText');if(label)label.textContent='Rumb '+Math.round(h)+'° · '+navCompassName(h)}
  function navUpdateTrack(){try{localStorage.setItem(NAV_TRACK_KEY,JSON.stringify(navTrack))}catch(_){}let m=0;for(let i=1;i<navTrack.length;i++)m+=navDistance(navTrack[i-1],navTrack[i]);const d=document.getElementById('navTrackDistance'),c=document.getElementById('navTrackCount'),t=document.getElementById('navTrackTime');if(d)d.textContent=m<1000?Math.round(m)+' m':(m/1000).toFixed(2)+' km';if(c)c.textContent=navTrack.length;if(t&&navTrack.length)t.textContent=Math.floor((navTrack[navTrack.length-1].time-navTrack[0].time)/60000)+' min';const x=document.getElementById('navTrackExport');if(x)x.disabled=navTrack.length<2;const cl=document.getElementById('navTrackClear');if(cl)cl.disabled=navTrack.length===0}
  function navBind(){document.getElementById('navLocate')?.addEventListener('click',()=>navGPS().then(p=>{navLast=p;document.getElementById('navPosition').textContent=p.lat.toFixed(6)+', '+p.lon.toFixed(6);document.getElementById('navAccuracy').textContent='Precisió estimada: ±'+Math.round(p.accuracy)+' m'+(p.alt!=null?' · Altitud: '+Math.round(p.alt)+' m':'');navStatus('Ubicació GPS actualitzada.')}).catch(()=>navStatus('No s’ha pogut obtenir GPS. Comprova permisos i ubicació.')));document.getElementById('navSaveBeacon')?.addEventListener('click',()=>{if(!navLast){navStatus('Primer obtén la ubicació GPS.');return}const name=document.getElementById('navBeaconName').value.trim()||'Punt guardat',s=navLoad();s.beacons.push({name,lat:navLast.lat,lon:navLast.lon});navSave(s);document.getElementById('navBeaconName').value='';navRenderBeacons();navStatus('Punt guardat en aquest dispositiu.')});navRenderBeacons();navUpdateTrack();document.getElementById('navTrackClear')?.addEventListener('click',()=>{if(!confirm('Vols esborrar el recorregut desat?'))return;navTrack=[];navUpdateTrack();navStatus('Recorregut esborrat del dispositiu.')});document.getElementById('navCompassBtn')?.addEventListener('click',async()=>{try{if(typeof DeviceOrientationEvent!=='undefined'&&typeof DeviceOrientationEvent.requestPermission==='function'&&await DeviceOrientationEvent.requestPermission()!=='granted')throw new Error('Permís denegat');window.addEventListener('deviceorientationabsolute',navOrientation,true);window.addEventListener('deviceorientation',navOrientation,true);navStatus('Brúixola activada. Contrasta la lectura amb un mapa.')}catch(e){navStatus('Brúixola no disponible: '+e.message)}});document.getElementById('navTrackStart')?.addEventListener('click',()=>{if(!navigator.geolocation||navWatch!==null)return;navTrack=[];navLast=null;navWatch=navigator.geolocation.watchPosition(p=>{if(p.coords.accuracy>60){navStatus('Precisió GPS baixa (±'+Math.round(p.coords.accuracy)+' m): esperant una lectura millor.');return}const q={lat:p.coords.latitude,lon:p.coords.longitude,time:p.timestamp};if(!navLast||navDistance(navLast,q)>=5){navTrack.push(q);navLast=q;navUpdateTrack()}},e=>navStatus('Error GPS: '+e.message),{enableHighAccuracy:true,maximumAge:3000,timeout:15000});document.getElementById('navTrackStart').disabled=true;document.getElementById('navTrackStop').disabled=false;navStatus('Registre GPS actiu. Mantén l’app oberta.')});document.getElementById('navTrackStop')?.addEventListener('click',()=>{if(navWatch!==null)navigator.geolocation.clearWatch(navWatch);navWatch=null;document.getElementById('navTrackStart').disabled=false;document.getElementById('navTrackStop').disabled=true;document.getElementById('navTrackExport').disabled=navTrack.length<2;navStatus('Registre aturat. Pots exportar el GPX.')});document.getElementById('navTrackExport')?.addEventListener('click',()=>{if(navTrack.length<2)return;const pts=navTrack.map(p=>'<trkpt lat="'+p.lat+'" lon="'+p.lon+'"><time>'+new Date(p.time).toISOString()+'</time></trkpt>').join(''),xml='<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="Supervivència" xmlns="http://www.topografix.com/GPX/1/1"><trk><name>Recorregut Supervivència</name><trkseg>'+pts+'</trkseg></trk></gpx>',url=URL.createObjectURL(new Blob([xml],{type:'application/gpx+xml'})),a=document.createElement('a');a.href=url;a.download='recorregut-supervivencia.gpx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)})}

  function renderFeature(){ const route=location.hash.replace('#',''); const main=document.querySelector('#main'); if(!main)return false; if(route==='phone')return false; if(route==='guides'){main.innerHTML=guidesPage();return true;} if(route==='scenario'){main.innerHTML=scenarioPage();main.querySelectorAll('[data-sim-answer]').forEach(b=>b.addEventListener('click',()=>scenarioAnswer(Number(b.dataset.simAnswer))));return true;} if(route==='map'){main.innerHTML=mapPage();bindMap();renderPOIMarkers();return true;} if(route==='navigation'){main.innerHTML=navPage();navBind();return true;} if(route==='radio'){main.innerHTML=radioPage();return true;}if(route==='phone'){main.innerHTML=phonePage();bindPhone();return true;}return false; }
  document.addEventListener('change',e=>{const input=e.target;if(input.matches('input[data-id="food"]')){syncFoodVisibility(input);return;}if(input.matches('input[data-food-item]')){const saved=loadFood();const key=`${input.dataset.foodType||'kit'}-${input.dataset.foodItem}`;saved[key]=input.checked;saveFood(saved);input.closest('.food-option')?.classList.toggle('done',input.checked);}});
  function decorate(){addFoodMenus();if(!renderFeature()&&['','home'].includes(location.hash.replace('#','')))addTools();if(location.hash.replace('#','')==='more'){const page=document.querySelector('.page');if(page&&!page.querySelector('[data-feature="navigation"]')){const nav=document.createElement('article');nav.className='card tile feature-tile';nav.dataset.feature='navigation';nav.innerHTML='<span class="emoji">🧭</span><div><h3>Orientació i retorn</h3><p>Brúixola, punts guardats i registre GPS</p></div>';page.querySelector('.grid')?.appendChild(nav);}if(page&&!page.querySelector('[data-feature="scenario"]')){const sim=document.createElement('article');sim.className='card tile feature-tile';sim.dataset.feature='scenario';sim.innerHTML='<span class="emoji">🎯</span><div><h3>Simulador d’emergències</h3><p>Practica decisions en quatre situacions</p></div>';page.querySelector('.grid')?.appendChild(sim);}if(page&&!page.querySelector('[data-feature="guides"]')){const card=document.createElement('article');card.className='card tile feature-tile';card.dataset.feature='guides';card.innerHTML='<span class="emoji">📘</span><div><h3>Guies pràctiques</h3><p>Primers auxilis, aigua segura i decisions en emergències</p></div>';page.querySelector('.grid')?.appendChild(card);}}}
  document.addEventListener('click',e=>{const feature=e.target.closest('[data-feature]');if(feature){location.hash=feature.dataset.feature;return;}if(e.target.closest('[data-feature-back]')){back();return;}});
  window.renderPhoneFeature=()=>location.hash.replace('#','')==='phone' ? renderFeature() : false;
  window.decorateFeatures=decorate;addEventListener('load',()=>setTimeout(decorate,0));setTimeout(decorate,50);
})();